mapper.insert:
insert into sys_role_dept(role_code, dept_id) select requested.role_code, requested.dept_id from (
select #{item.roleCode} as role_code, #{item.deptId} as dept_id
) requested join sys_role r on r.role_code = requested.role_code join sys_dept d on d.dept_id = requested.dept_id where r.role_type = 'PLATFORM' and r.shop_code = '' and r.del_flag = '0' and d.shop_code = '' and d.del_flag = '0'
